static WL_SHM_RELEASE_REQUEST_TYPES: [IfacePtr; 0] = [];
static WL_SHM_REQUESTS: [wl_message; 2] = [
    wl_message {
        name: c"create_pool".as_ptr(),
        signature: c"nhi".as_ptr(),
        types: WL_SHM_CREATE_POOL_REQUEST_TYPES.as_ptr(),
    },
    wl_message {
        name: c"release".as_ptr(),
        signature: c"2".as_ptr(),
        types: WL_SHM_RELEASE_REQUEST_TYPES.as_ptr(),
    },
];
static WL_SHM_FORMAT_EVENT_TYPES: [IfacePtr; 1] = [None];
static WL_SHM_EVENTS: [wl_message; 1] = [wl_message {
    name: c"format".as_ptr(),
    signature: c"u".as_ptr(),
    types: WL_SHM_FORMAT_EVENT_TYPES.as_ptr(),
}];
/// The `wl_interface` of `wl_shm` (`wl_shm_interface`).
pub(crate) static WL_SHM_INTERFACE: wl_interface = wl_interface {
    name: c"wl_shm".as_ptr(),
    version: 3,
    method_count: 2,
    methods: WL_SHM_REQUESTS.as_ptr(),
    event_count: 1,
    events: WL_SHM_EVENTS.as_ptr(),
};

/// `wl_shm.error`: wl_shm error values
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug, Default)]
pub(crate) struct WlShmError(pub(crate) u32);

impl WlShmError {
    /// buffer format is not known
    pub(crate) const INVALID_FORMAT: WlShmError = WlShmError(0);
    /// invalid size or stride during pool creation
    pub(crate) const INVALID_STRIDE: WlShmError = WlShmError(1);
    /// mmapping the file descriptor failed
    pub(crate) const INVALID_FD: WlShmError = WlShmError(2);
}

