/// `wl_shell_surface.fullscreen_method`: different method to set the surface fullscreen
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug, Default)]
pub(crate) struct WlShellSurfaceFullscreenMethod(pub(crate) u32);

impl WlShellSurfaceFullscreenMethod {
    /// no preference, apply default policy
    pub(crate) const DEFAULT: WlShellSurfaceFullscreenMethod = WlShellSurfaceFullscreenMethod(0);
    /// scale, preserve the surface's aspect ratio and center on output
    pub(crate) const SCALE: WlShellSurfaceFullscreenMethod = WlShellSurfaceFullscreenMethod(1);
    /// switch output mode to the smallest mode that can fit the surface, add black borders to compensate size mismatch
    pub(crate) const DRIVER: WlShellSurfaceFullscreenMethod = WlShellSurfaceFullscreenMethod(2);
    /// no upscaling, center on output and add black borders to compensate size mismatch
    pub(crate) const FILL: WlShellSurfaceFullscreenMethod = WlShellSurfaceFullscreenMethod(3);
}

