    /// surface was destroyed before its role object
    pub(crate) const DEFUNCT_ROLE_OBJECT: WlSurfaceError = WlSurfaceError(4);
    /// no buffer was attached
    pub(crate) const NO_BUFFER: WlSurfaceError = WlSurfaceError(5);
