/// `wl_seat.capability`: seat capability bitmask
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug, Default)]
pub(crate) struct WlSeatCapability(pub(crate) u32);

impl WlSeatCapability {
    /// the seat has pointer devices
    pub(crate) const POINTER: WlSeatCapability = WlSeatCapability(1);
    /// the seat has one or more keyboards
    pub(crate) const KEYBOARD: WlSeatCapability = WlSeatCapability(2);
    /// the seat has touch devices
    pub(crate) const TOUCH: WlSeatCapability = WlSeatCapability(4);

    /// Whether all the bits of `other` are set.
    pub(crate) const fn contains(self, other: WlSeatCapability) -> bool {
        self.0 & other.0 == other.0
    }
}

impl std::ops::BitOr for WlSeatCapability {
    type Output = WlSeatCapability;
    fn bitor(self, rhs: WlSeatCapability) -> WlSeatCapability {
        WlSeatCapability(self.0 | rhs.0)
    }
}

impl std::ops::BitOrAssign for WlSeatCapability {
    fn bitor_assign(&mut self, rhs: WlSeatCapability) {
        self.0 |= rhs.0;
    }
}

